from comic2svg.optimizer import round_path_coordinates, optimize_svg_content, optimize_svg


def test_round_path_coordinates():
    raw_path = "M 10.123456 20.987654 L 30.555555 40.111111 Z"
    rounded = round_path_coordinates(raw_path, precision=2)
    assert "10.12" in rounded
    assert "20.99" in rounded
    assert "30.56" in rounded
    assert "40.11" in rounded


def test_optimize_svg_content():
    raw_svg = """<?xml version="1.0" encoding="utf-8"?>
<!-- Generated by vtracer -->
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100">
  <metadata>Unneeded metadata</metadata>
  <g>
    <path d="M 12.34567 89.12345 C 23.45678 34.56789 45.67891 56.78912 67.89123 78.91234 Z" fill="#000" />
    <path d="" />
  </g>
</svg>"""

    optimized = optimize_svg_content(raw_svg, precision=2)
    assert "<?xml" not in optimized
    assert "<!-- Generated" not in optimized
    assert "<metadata>" not in optimized
    assert "12.35" in optimized
    assert "89.12" in optimized
    assert len(optimized) < len(raw_svg)


def test_optimize_svg_file(tmp_path):
    svg_file = tmp_path / "test.svg"
    raw_svg = """<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100">
  <!-- comment -->
  <path d="M 1.11111 2.22222 L 3.33333 4.44444" />
</svg>"""
    svg_file.write_text(raw_svg, encoding="utf-8")

    out_file, stats = optimize_svg(svg_file, precision=1)
    assert out_file.exists()
    assert stats.saved_bytes > 0
    assert stats.savings_percent > 0
